"""Row and vector evaluation of NetNomos formulas over prepared window frames.

All arithmetic is exact integer arithmetic on ``int64`` columns: sums may cross
fields and slots, scaling is a plain product, and neither wraps nor saturates.
Intermediate values need not belong to any declared domain.
"""
from __future__ import annotations

from typing import Any, Iterable, Mapping
