#: Internal comparator spellings mapped onto exact integer numpy comparisons.
COMPARATORS: dict[str, Any] = (
    {
        "=": np.equal,
        "!=": np.not_equal,
        "<": np.less,
        "<=": np.less_equal,
        ">": np.greater,
        ">=": np.greater_equal,
    }
    if np is not None
    else {}
)

Env = Mapping[str, Any]


