# ------------------------------------------------------------------------ vectors
def evaluate_term_vector(term: Term, prepared: PreparedDataset, env: Env | None = None) -> Any:
    """Vectorised term value: an ``int64`` column, or an exact Python integer."""
    env = env or {}
    if isinstance(term, Constant):
        return int(term.value)
    if isinstance(term, SymbolRef):
        return prepared.column(term.name)
    if isinstance(term, IndexedRef):
        return prepared.column(resolve_indexed_name(term, env, prepared.context_families))
    if isinstance(term, BinaryTerm):
        left = evaluate_term_vector(term.left, prepared, env)
        right = evaluate_term_vector(term.right, prepared, env)
        if term.op == "+":
            return np.add(left, right, dtype=np.int64)
        if term.op == "-":
            return np.subtract(left, right, dtype=np.int64)
        if term.op == "*":
            return np.multiply(left, right, dtype=np.int64)
        raise ValueError(f"Unsupported term op: {term.op}")
    if isinstance(term, FuncCall):
        name = term.name.lower()
        values = [evaluate_term_vector(arg, prepared, env) for arg in term.args]
        if name == "sum":
            total: Any = 0
            for value in values:
                total = np.add(total, value, dtype=np.int64)
            return total
        if name in {"min", "max"}:
            stacked = np.stack(np.broadcast_arrays(*(np.asarray(value, dtype=np.int64) for value in values)))
            reduce = np.minimum.reduce if name == "min" else np.maximum.reduce
            return reduce(stacked, axis=0)
        raise ValueError(f"Unsupported function: {term.name}")
    raise TypeError(f"Unsupported term node: {type(term)!r}")


def evaluate_formula_vector(
    formula: Formula, prepared: PreparedDataset, env: Env | None = None
) -> np.ndarray:
    """Truth value of ``formula`` for every row of ``prepared`` as a bool column."""
    env = env or {}
    length = prepared.length
    if isinstance(formula, BoolConst):
        return np.full(length, bool(formula.value), dtype=bool)
    if isinstance(formula, Compare):
        comparator = COMPARATORS[formula.op]
        left = evaluate_term_vector(formula.left, prepared, env)
        right = evaluate_term_vector(formula.right, prepared, env)
        result = comparator(left, right)
        if isinstance(result, np.ndarray) and result.ndim:
            return result if result.dtype == np.bool_ else result.astype(bool)
        # A degenerate constant comparison still has one truth value per row.
        return np.full(length, bool(result), dtype=bool)
    if isinstance(formula, BoolNot):
        return ~evaluate_formula_vector(formula.value, prepared, env)
    if isinstance(formula, BoolAnd):
        return _reduce_bool(formula.values, prepared, env, np.logical_and, True)
    if isinstance(formula, BoolOr):
        return _reduce_bool(formula.values, prepared, env, np.logical_or, False)
    if isinstance(formula, Implies):
        left = evaluate_formula_vector(formula.left, prepared, env)
        right = evaluate_formula_vector(formula.right, prepared, env)
        return (~left) | right
    if isinstance(formula, (ForAll, Exists)):
        identity = isinstance(formula, ForAll)
        accumulator: np.ndarray | None = None
        for value in formula.domain:
            body = evaluate_formula_vector(formula.body, prepared, {**env, formula.variable: value})
            accumulator = body.copy() if accumulator is None else (
                (accumulator & body) if identity else (accumulator | body)
            )
        if accumulator is None:
            return np.full(length, identity, dtype=bool)
        return accumulator
    raise TypeError(f"Unsupported formula node: {type(formula)!r}")


